import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"QEMU 测试","description":"","frontmatter":{},"headers":[],"relativePath":"zh/dev/qemu-testing.md","filePath":"zh/dev/qemu-testing.md"}'),d={name:"zh/dev/qemu-testing.md"};function i(n,e,l,c,r,p){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="qemu-测试" tabindex="-1">QEMU 测试 <a class="header-anchor" href="#qemu-测试" aria-label="Permalink to &quot;QEMU 测试&quot;">​</a></h1><p>项目在 QEMU 中实际如何测试 - 与发布门禁使用的相同配方。</p><h2 id="交互式启动" tabindex="-1">交互式启动 <a class="header-anchor" href="#交互式启动" aria-label="Permalink to &quot;交互式启动&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make run-bios      # default: 512M, e1000 + user net, serial on stdio</span></span>
<span class="line"><span>make run-uefi      # q35 + OVMF</span></span>
<span class="line"><span>make run-bios-gui  # display on (for the TUI)</span></span></code></pre></div><p><code>run-*</code> 目标会构建 ISO 和一个全新的 <code>etc.img</code>（32 MiB 的 FAT32 /etc 卷），让持久性测试从干净状态开始。</p><h2 id="确定性的启动日志测试" tabindex="-1">确定性的启动日志测试 <a class="header-anchor" href="#确定性的启动日志测试" aria-label="Permalink to &quot;确定性的启动日志测试&quot;">​</a></h2><p>回归套件（<code>tools/run_fix4_regression.py</code>）通过 pexpect 在 <code>-serial mon:stdio</code> 上驱动 QEMU：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 tools/run_fix4_regression.py build/opencube.iso out.log</span></span></code></pre></div><p>它等待 <code>ush&gt;</code> 提示符，然后运行固定的命令组（uname、help -a、 heaptest、fstest、cryptotest、crashlog、l1test，以及整套 <code>run *test</code> 用户程序），并在合并输出上断言 28 项检查 - 启动 横幅、自检、L0 命令数、每个测试的 PASS 行。零失败是门槛。</p><h2 id="看门狗-日志-e2e" tabindex="-1">看门狗 / 日志 E2E <a class="header-anchor" href="#看门狗-日志-e2e" aria-label="Permalink to &quot;看门狗 / 日志 E2E&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 tools/wp12_watchdog_logging_e2e.py build/opencube.iso</span></span></code></pre></div><p>14 个场景：klog 写入/刷新/轮转/过滤链、看门狗状态/槽位/策略 击杀、健康分组 + JSON 导出 + CPU 告警，以及两个<em>真实硬件复位</em> 场景 - S12 以 <code>-no-reboot</code> 启动一台 q35 机器，发现 Intel TCO、 布防它、饿死它并断言第二次启动；S13 通过 ACPI WDAT 做同样的 事。</p><h2 id="网络-e2e" tabindex="-1">网络 E2E <a class="header-anchor" href="#网络-e2e" aria-label="Permalink to &quot;网络 E2E&quot;">​</a></h2><ul><li><strong>SSH E2E</strong>：启动客户机内的 <code>sshd</code>，然后从宿主机通过 paramiko 登录 - 完整的密钥交换、会话、命令往返。需要 /etc 卷 预置主机密钥（<code>host_keygen_etc</code>）。</li><li><strong>HTTPS E2E</strong>：对一台参考 TLS 服务器执行 <code>wget https://&lt;host&gt;</code><ul><li>握手、证书验证、正文保存、close_notify。</li></ul></li></ul><p>两个套件都是发布门禁；其完整机制见 <a href="./e2e-suites.html">e2e-suites.md</a>。</p><h2 id="截图" tabindex="-1">截图 <a class="header-anchor" href="#截图" aria-label="Permalink to &quot;截图&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make shot-bios     # boot screenshot to build/shot-bios.ppm</span></span>
<span class="line"><span>make shot-uefi</span></span></code></pre></div><h2 id="映射到驱动的-qemu-设备" tabindex="-1">映射到驱动的 QEMU 设备 <a class="header-anchor" href="#映射到驱动的-qemu-设备" aria-label="Permalink to &quot;映射到驱动的 QEMU 设备&quot;">​</a></h2><table tabindex="0"><thead><tr><th>QEMU 标志</th><th>内核驱动</th></tr></thead><tbody><tr><td><code>-device e1000</code>（默认网络）</td><td>e1000 网卡</td></tr><tr><td><code>-device virtio-blk-pci</code></td><td>virtio-blk</td></tr><tr><td><code>-device nvme</code></td><td>NVMe</td></tr><tr><td>经 xHCI 的 <code>-device usb-storage</code></td><td>USB MSC</td></tr><tr><td><code>-device AC97</code> / <code>-device intel-hda</code></td><td>声音</td></tr><tr><td>q35 机型</td><td>Intel TCO 看门狗</td></tr><tr><td><code>-bios OVMF.fd</code></td><td>UEFI 启动路径</td></tr></tbody></table><h2 id="速度" tabindex="-1">速度 <a class="header-anchor" href="#速度" aria-label="Permalink to &quot;速度&quot;">​</a></h2><ul><li>每次自动化运行都使用 <code>-display none -serial mon:stdio</code>。</li><li>在回归环境中启动到 <code>ush&gt;</code> 提示符约需 2 秒墙上时间；完整的 28 项检查组远在一分钟内跑完。</li></ul>`,21)])])}const b=t(d,[["render",i]]);export{u as __pageData,b as default};
